// === Tab: mySketch ===
let theShader
let myShader
let lastMouse
let nextMouse
let particles = []
function draw() {
		nextMouse.set((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
		initDraw()
		const positions = getPositions(particles);
		shader(myShader)
		const screenDensity = displayDensity()
		myShader.setUniform("u_resolution", [windowWidth*screenDensity, windowHeight*screenDensity]);
		myShader.setUniform("u_positions", positions);
		myShader.setUniform("u_position_count", positions.length / 2);

		rect(0, 0, windowWidth, windowHeight)
		const delta = p5.Vector.sub(nextMouse, lastMouse)
		if (delta.mag() > 10) {
				generateParticles(p5, delta)
		}
		showParticles()
		lastMouse.set((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
}

function setup() {
		var canvas = createCanvas(windowWidth, windowHeight, WEBGL)
		lastMouse = createVector(0, 0)
		nextMouse = createVector(0, 0)
}


function preload() {
	myShader = createShader(vertShader, fragShader);
}


function initDraw() {
    fill(255)
    translate(-windowWidth / 2, -windowHeight / 2)
}

function showParticles() {
    for (let i = particles.length - 1; i > -1; i--) {
        particles[i].show()
        if (particles[i].isDead) {
            particles.splice(i, 1)
        }
    }
}

function mousePressed() {
noLoop();
}

function generateParticles(p5, delta) {particles.push(new Particle(nextMouse, delta))}

function getPositions(particles) {
    var positions = []
    for (let i = 0; i < particles.length; i++) {
        positions.push(
            map(particles[i].position.x, 0,windowWidth, 0, 1),
            1 - map(particles[i].position.y, 0, windowHeight, 0, 1)
        )
    }
    return positions
}

class Particle {
    position;
    delta;
    lifeSpan = 25;
    isDead = false;
    velocity = 0.9;
    constructor(position, deltaDistance) {
        this.position = createVector(position.x, position.y)
        this.delta = deltaDistance
    }

    show() {
        pow(0.5, this.velocity)
        this.delta.mult(this.velocity)
        this.position.add(this.delta)
        if (this.lifeSpan < 0) {
            this.isDead = true
        } else {
            this.lifeSpan -= 1
        }
    }

}


var vertShader = `

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`

var fragShader = `
precision mediump float;
varying vec2 vTexCoord;
uniform vec2 u_resolution;
uniform vec2 u_positions[90];
uniform int u_position_count;

void main() {
	vec3 destColor = vec3(0.0);
float ratio = u_resolution.x/u_resolution.y;
vec2 st = gl_FragCoord.xy/u_resolution.xy;
    for (int j = 0; j < 90; j++) {
        if(j < u_position_count) {
        vec2 particle = u_positions[j];
// -st.x乘長寬讓畫面比例正確，particle.x乘長寬比讓光點的比例正確
		float a = (-st.x+ particle.x)*ratio;
		float b = -st.y + particle.y;

        // style 1 

        // 如果光點很少，j的值就小，k算出來就大，乘上任何顏色都會放大光點顏色，光點越多越能放大顏色
        float k = float(j) * 0.1;
        // 如果光點很少，90-j的值就大，kk算出來就大，乘上任何顏色都會放大光點顏色，光點多則會縮小顏色
        float kk = float(90-j) * 0.01;
        // 乘上這個數上的話，如果st.x位於particle.x附近，都會被放大
        float xRadiation = (abs(a)*100.0) * 0.1;
        // 乘上這個數上的話，如果st.y位於particle.y附近，都會被放大
        float yRadiation = (abs(b)*100.0) * 0.05;
        float minorPositiveA = 0.1 * abs(a);
        float minorPositiveB = 0.1 * abs(b);
        float vertical_bar = 2.0/abs(a);
        float horizintal_bar = 2.0/abs(b);
		destColor.r += 0.003 / sqrt(a*a+b*b) * k * yRadiation + (0.003 / sqrt(a*a+b*b) * k);
		destColor.g += (0.003 / sqrt(a*a+b*b) * vertical_bar * horizintal_bar * 0.0000001 + 0.01) + 0.003 / sqrt(a*a+b*b) * k * kk;
        // 直接在加在rgb的數值為這個點以外的地方加亮，因為直接幫每個pixel加亮
        // vertical_bar：等式0.003 / sqrt(a*a+b*b)乘上數值2.0/abs(a)，讓destColor變得很小，除非vTexCoord.x位於particle.x上
		destColor.b += 0.003 / sqrt(a*a+b*b) * k * kk;

        // style 2

        // float k = float(j) * 0.1;
        // float reverseA = 10.0 * abs(a);
        // float reverseB = 10.0 *  abs(b);
		// destColor.r += (0.003 / sqrt(a*a+b*b)) * reverseA +  0.003 / sqrt(a*a+b*b)* k;
		// destColor.g += 0.003 / sqrt(a*a+b*b)* k;
		// destColor.b += 0.003 / sqrt(a*a+b*b) * reverseB +  0.003 / sqrt(a*a+b*b)* k;

        };
    };
    gl_FragColor = vec4(destColor,1.0);
}`

